{
  "application": "ppt-generation",
  "case_id": "case-ultrasound-eth-supply",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "crypto-native investors and Ethereum ecosystem participants evaluating ETH as a monetary asset",
    "tone": "data-forward, analytical, conviction-driven"
  },
  "brief": {
    "title": "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics and Monetary Premium",
    "one_liner": "A data-driven analysis of Ethereum's supply mechanics post-merge, covering burn rates, issuance, staking economics, and long-term supply projections that underpin the 'ultra sound money' thesis.",
    "goal": "Equip the audience with a clear understanding of ETH's deflationary mechanics, current supply trajectory, burn/issuance dynamics, and how these compare to Bitcoin and traditional stores of value — enabling informed conviction on ETH's monetary properties."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "Ultra Sound Money: Ethereum's Supply Dynamics & Monetary Thesis",
      "objective": "Cover slide with deck title, subtitle referencing post-merge ETH economics, and key context: current supply ~121.6M ETH, current gas ~0.1 Gwei, ETH price ~$2,243."
    },
    {
      "id": "supply-change-snapshot",
      "title": "ETH Supply Growing at +0.83%/Year with Only 192 ETH Burned in 7 Days",
      "objective": "Present the 7-day supply change snapshot: +19,445.89 ETH net change, 192.39 ETH burned vs 19,638.29 ETH issued. Show the current supply of 121,603,980 ETH. Use a simple waterfall or bar chart showing issuance vs burn to illustrate the offset ratio of 0.01x."
    },
    {
      "id": "gas-and-burn-mechanics",
      "title": "Base Gas at Historic Lows: 0.1 Gwei Average Suppresses Fee Burn",
      "objective": "Explain the EIP-1559 burn mechanism and show current gas market data: min 0.0, max 1.3, average 0.1 Gwei. Include blob gas context (avg ~7.1M wei, with only 0.15 ETH in blob fees burned over 7 days). Visualize with a range/gauge chart. Note that the 22 Gwei equilibrium assumption used in long-term projections is far above current levels. Convey that low gas = low burn = temporary supply inflation."
    },
    {
      "id": "burn-leaderboard-categories",
      "title": "DeFi and ETH Transfers Account for 85% of Weekly Fee Burn",
      "objective": "Show the burn categories table (defi 31 ETH, ETH transfers 22 ETH, misc 4, NFTs 3, contract creations 2, L2/MEV/blobs 0). Include top burn leaderboard entries (ETH transfers 21.7 ETH, Tether 13.6 ETH, etc.). Use a horizontal bar chart or treemap for categories."
    },
    {
      "id": "staking-and-validator-economics",
      "title": "38.9M ETH Staked at 2.7% Issuance Rewards with Minimal Tips and MEV",
      "objective": "Present staking economics: 38.9M ETH staked, validator rewards breakdown (issuance 2.7% APR, tips 0.1%, MEV 0.1%). Show the scarcity engine: staking contracts lock 9.1M ETH for avg 10.7 years. Use a stacked bar or donut chart for reward composition."
    },
    {
      "id": "supply-projections",
      "title": "Long-Term Equilibrium Projected at 125.7M ETH with 1,037K ETH/Year Issuance-Burn Balance",
      "objective": "Show the 200-year supply projection converging to 125.7M ETH equilibrium. Reference the 2-year projection chart showing historical supply growth across eras (genesis 5 ETH/block → merge PoW removal). Include key parameters: 39M staked, 22 Gwei base gas assumption, 2.8K ETH/day PoS issuance vs 2.2K ETH/day burn. Use a line chart visualization."
    },
    {
      "id": "flippening-and-tvs",
      "title": "ETH at 18.7% of Bitcoin's Market Cap, Securing $272B in Native Value",
      "objective": "Present the flippening progress (BTC 18.7%, gold 0.89%, USD 1.30%) and Total Value Secured breakdown: ETH $272.76B, ERC20s $22.21B, NFTs $12.66B. Include top ERC20s (Dai $4.41B, SHIB $3.51B) and top NFTs (CryptoPunks $2.13B). Use a stacked bar or pie chart for TVS composition."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways: Ultra Sound Money Thesis Intact but Gas Activity Is the Critical Variable",
      "objective": "Summarize 4-5 key findings: (1) ETH is currently slightly inflationary at +0.83%/yr due to historically low gas, (2) burn mechanism works but requires sustained on-chain activity, (3) 38.9M ETH staked creates significant supply lock, (4) long-term equilibrium at 125.7M ETH is structurally sound, (5) flippening progress and $307B+ TVS demonstrate growing monetary premium. End with forward-looking implications for investors."
    }
  ]
}

